/* Builds design-system/_ds_bundle.js, the browser bundle the component
   preview cards (design-system/components/<group>/<group>.card.html) load.
   It is assets/motion.js followed by every component. React comes from the
   page as the global `React`; every component lands on
   window.ElementalUIDesignSystem_5d6c38. Run with `npm run build:ds`. */
import { build } from 'vite';
import { mkdirSync, readdirSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join, relative } from 'node:path';

const NAMESPACE = 'ElementalUIDesignSystem_5d6c38';
const root = fileURLToPath(new URL('../design-system/', import.meta.url));
const componentsDir = join(root, 'components');
const tmp = fileURLToPath(new URL('../node_modules/.ds-bundle/', import.meta.url));
const outDir = join(tmp, 'out');

const components = readdirSync(componentsDir, { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .flatMap((d) => readdirSync(join(componentsDir, d.name))
    .filter((f) => f.endsWith('.jsx'))
    .map((f) => ({ name: f.replace(/\.jsx$/, ''), path: join(componentsDir, d.name, f) })))
  .sort((a, b) => a.name.localeCompare(b.name));

const entry = join(tmp, 'entry.js');
mkdirSync(tmp, { recursive: true });
writeFileSync(entry, components.map((c) => `export * from ${JSON.stringify(c.path)};`).join("\n"));

await build({
  configFile: false,
  logLevel: 'warn',
  oxc: { jsx: { runtime: 'classic' } },
  build: {
    outDir,
    emptyOutDir: true,
    minify: false,
    lib: { entry, formats: ['iife'], name: NAMESPACE, fileName: () => 'bundle.js' },
    rollupOptions: { external: ['react'], output: { globals: { react: 'React' } } },
  },
});

const header = { format: 'vite-iife', namespace: NAMESPACE, components: components.map((c) => ({ name: c.name, sourcePath: relative(root, c.path) })) };
const motion = readFileSync(join(root, 'assets/motion.js'), 'utf8');
const code = readFileSync(join(outDir, 'bundle.js'), 'utf8');
writeFileSync(join(root, '_ds_bundle.js'), `/* @ds-bundle: ${JSON.stringify(header)} */\n/* Generated by scripts/build-ds-bundle.mjs. Do not edit by hand. */\n\n// assets/motion.js\n${motion}\n${code}`);
rmSync(tmp, { recursive: true, force: true });
console.log(`_ds_bundle.js: ${components.length} components`);
